    private static int[]? _keys;      // sorted 24-bit prefixes
    private static byte[]? _vendor;   // index into Vendors, parallel to _keys
    private static readonly object Gate = new();

    /// <summary>
    /// The maker for a MAC in any common notation (A8:5E:45:BB:13:7D, a8-5e-45-…, a85e.45bb.137d), "" when the prefix
    /// isn't in the table. A locally administered address has no maker: it's a randomised (private) address — phones
    /// and laptops use one per network — or a virtual NIC, and is reported as such.
    /// </summary>
    public static string Vendor(string? mac)
    {
        if (!TryParse(mac, out int prefix)) return "";
        int first = prefix >> 16;
        if ((first & 0x01) != 0) return "";                      // multicast / broadcast: not a host
        if ((first & 0x02) != 0) return "Private address";       // locally administered (randomised / virtual)
        EnsureLoaded();
        int i = Array.BinarySearch(_keys!, prefix);
        return i >= 0 ? Vendors[_vendor![i]] : "";
    }

    /// <summary>A unicast, globally or locally administered host MAC (not all-zero, not multicast/broadcast).</summary>
    public static bool IsHostMac(string? mac)
    {
        if (!TryParse(mac, out int prefix, out bool allZero)) return false;
        return !allZero && ((prefix >> 16) & 0x01) == 0;
    }

    /// <summary>Upper-case colon notation ("A8:5E:45:BB:13:7D"), or the input unchanged if it isn't a 6-byte MAC.</summary>
    public static string Format(string mac)
    {
        Span<char> hex = stackalloc char[12];
        int n = 0;
        foreach (char c in mac)
        {
            if (Uri.IsHexDigit(c)) { if (n == 12) return mac; hex[n++] = char.ToUpperInvariant(c); }
            else if (c is not (':' or '-' or '.')) return mac;
        }
        if (n != 12) return mac;
        return string.Create(17, hex.ToString(), static (dst, h) =>
        {
            for (int i = 0, j = 0; i < 12; i += 2)
            {
                if (i > 0) dst[j++] = ':';
                dst[j++] = h[i]; dst[j++] = h[i + 1];
            }
        });
    }

    private static bool TryParse(string? mac, out int prefix) => TryParse(mac, out prefix, out _);

    private static bool TryParse(string? mac, out int prefix, out bool allZero)
    {
        prefix = 0; allZero = true;
        if (string.IsNullOrEmpty(mac)) return false;
        int digits = 0;
        foreach (char c in mac)
        {
            if (c is ':' or '-' or '.') continue;
            int v = c is >= '0' and <= '9' ? c - '0' : c is >= 'a' and <= 'f' ? c - 'a' + 10 : c is >= 'A' and <= 'F' ? c - 'A' + 10 : -1;
            if (v < 0 || digits == 12) return false;
            if (digits < 6) prefix = (prefix << 4) | v;
            if (v != 0) allZero = false;
            digits++;
        }
        return digits == 12;
    }

    private static void EnsureLoaded()
    {
        if (Volatile.Read(ref _keys) is not null) return;
        lock (Gate)
        {
            if (Volatile.Read(ref _keys) is not null) return;
            byte[] blob = Convert.FromBase64String(Blob);
            int pos = 0, total = 0;
            int ReadVarint()
            {
                int v = 0, shift = 0;
                while (true)
                {
                    byte b = blob[pos++];
                    v |= (b & 0x7F) << shift;
                    if ((b & 0x80) == 0) return v;
                    shift += 7;
                }
            }
            // First pass: count; second: fill. Each vendor block is [count][delta]...
            for (int v = 0; v < Vendors.Length; v++)
            {
                int count = ReadVarint();
                total += count;
                for (int k = 0; k < count; k++) ReadVarint();
            }
            var keys = new int[total];
            var vendor = new byte[total];
            pos = 0;
            int at = 0;
            for (int v = 0; v < Vendors.Length; v++)
            {
                int count = ReadVarint(), prev = 0;
                for (int k = 0; k < count; k++)
                {
                    prev += ReadVarint();
                    keys[at] = prev; vendor[at] = (byte)v; at++;
                }
            }
            Array.Sort(keys, vendor);
            _vendor = vendor;
            Volatile.Write(ref _keys, keys);   // published last: the unlocked fast path reads it
        }
    }
